import { createCourseBuilder } from '../CourseBuilder';
import { defineHole } from '../Hole';
const v=(x:number,y:number,z:number)=>({x,y,z});
const deck=(id:string,x:number,z:number,sx:number,sz:number,y=0)=>({id,transform:{position:v(x,y,z)},shape:'box' as const,size:v(sx,.45,sz),material:'wood' as const,friction:.72});
