const cup=(x:number,z:number,y=.4)=>({position:v(x,y,z),radius:.32,captureDepth:.35});
const bounds=(W:number,L:number)=>({min:v(-W/2-2,-5,-2),max:v(W/2+2,9,L+2)});
export const pirateBayCourse=createCourseBuilder({id:'pirate-bay',name:'Pirate Bay',themeId:'pirate-bay'}).addHoles([
defineHole({id:'pb-01-dockside-putt',name:'Dockside Putt',par:2,spawn:v(0,.5,1),cup:cup(0,13),bounds:bounds(8,14),surfaces:[deck('dock',0,7,6,14)],obstacles:[wall('port',-3.2,7,.4,14),wall('starboard',3.2,7,.4,14)]}),
defineHole({id:'pb-02-crate-alley',name:'Crate Alley',par:3,spawn:v(0,.5,1),cup:cup(0,16),bounds:bounds(10,17),surfaces:[deck('dock',0,8.5,8,17)],obstacles:[{id:'crate-a',type:'block',transform:{position:v(-1.8,.8,7)},size:v(2,1.6,2)},{id:'crate-b',type:'block',transform:{position:v(1.8,.8,11)},size:v(2,1.6,2)}]}),
defineHole({id:'pb-03-cannon-bank',name:'Cannon Bank',par:3,spawn:v(-2,.5,1),cup:cup(2,17),bounds:bounds(11,18),surfaces:[deck('deck',0,9,9,18)],obstacles:[{id:'cannon-a',type:'bumper',transform:{position:v(-1.8,.6,9)},size:v(1.2,1.2,3),restitution:.85},{id:'cannon-b',type:'bumper',transform:{position:v(1.8,.6,12)},size:v(1.2,1.2,3),restitution:.85}]}),
defineHole({id:'pb-04-plank-crossing',name:'Plank Crossing',par:4,spawn:v(-2,.5,1),cup:cup(2,19),bounds:bounds(13,20),surfaces:[deck('dock-a',-2,5,7,10),deck('plank',0,11,2,5,.15),deck('dock-b',2,16,7,8)],obstacles:[sea('harbor',0,11,13,6),wall('plank-port',-1.2,11,.25,5),wall('plank-starboard',1.2,11,.25,5)]}),
defineHole({id:'pb-05-rolling-barrels',name:'Rolling Barrels',par:4,spawn:v(0,.5,1),cup:cup(0,20),bounds:bounds(12,21),surfaces:[deck('deck',0,10.5,9,21)],obstacles:[{id:'barrel-gate',type:'gate',transform:{position:v(0,1,9)},size:v(7,1.5,.7),motion:{kind:'translate',axis:v(1,0,0),speed:1.4,distance:2.6}},{id:'mast',type:'pillar',transform:{position:v(0,1.4,15)},size:v(1.5,2.8,1.5)}]}),
defineHole({id:'pb-06-crows-nest',name:"Crow's Nest",par:4,spawn:v(0,.5,1),cup:cup(0,20,1.7),bounds:bounds(12,21),surfaces:[deck('approach',0,5,8,10),{id:'gangway',transform:{position:v(0,.9,11)},shape:'ramp',size:v(5,1.8,6),material:'wood'},deck('upper',0,17,8,8,1.3)],obstacles:[{id:'mast-spinner',type:'spinner',transform:{position:v(0,2,16)},size:v(7,.5,.5),motion:{kind:'rotate',axis:v(0,1,0),speed:1.2}}]}),
defineHole({id:'pb-07-shark-channel',name:'Shark Channel',par:5,spawn:v(-3,.5,1),cup:cup(3,22),bounds:bounds(15,23),surfaces:[deck('start',-3,5,6,10),deck('mid',0,12,4,5),deck('finish',3,19,6,8)],obstacles:[sea('channel',0,13,15,18),{id:'ferry',type:'platform',transform:{position:v(0,.3,15)},size:v(3,.4,5),motion:{kind:'translate',axis:v(1,0,0),speed:1,distance:3}}]}),
